SOURCE='def precompute_xor_prefixes(values):\n    xor_prefixes = [0] * (len(values) + 1)\n    for i in range(len(values)):\n        xor_prefixes[i+1] = xor_prefixes[i] ^ values[i]\n    return xor_prefixes\n\n# 读取输入并处理\nvalues = list(map(int, input().split()))\nxor_prefixes = precompute_xor_prefixes(values)\n\n# 读取查询并处理\nfor _ in range(10000):\n    L, R = map(int, input().split())\n    result = xor_prefixes[R+1] ^ xor_prefixes[L]\n    print(result)\n'
with tempfile.NamedTemporaryFile('w',suffix='.py') as f:
 f.write(SOURCE); f.flush()
 root=Path(__file__).parent/'data'
 for i,c in enumerate(CASES):
  o=subprocess.run(['python3',f.name],input=c,text=True,capture_output=True,check=True).stdout
  (root/f'{i}.in').write_text(c); (root/f'{i}.out').write_text(o)
